create table if not exists storage_objects(id uuid primary key,cid varchar(120) not null unique,sha256 char(64) not null,size_bytes bigint not null,filename varchar(500),content_type varchar(160),tags text[] not null default '{}',owner_agent_id uuid,retention_days integer not null,replicas integer not null,status varchar(24) not null check(status in('uploaded','committing','active','degraded','expired','failed')),ipfs_provider varchar(120),dataset_id varchar(160),piece_cid varchar(160),payment_rail_id varchar(160),proof_status varchar(24),expires_at timestamptz not null,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create index if not exists storage_objects_search_idx on storage_objects using gin(tags);
create index if not exists storage_objects_owner_idx on storage_objects(owner_agent_id,created_at desc);
create table if not exists storage_receipts(id uuid primary key,object_id uuid not null references storage_objects(id),quote_id uuid not null references service_quotes(id),kind varchar(24) not null check(kind in('ipfs_upload','filecoin_commitment','pdp_proof','retrieval')),provider varchar(160),external_id varchar(200),status varchar(24) not null check(status in('pending','confirmed','failed')),tx_hash varchar(160),metadata jsonb not null default '{}',created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create index if not exists storage_receipts_pending_idx on storage_receipts(status,created_at);
create table if not exists retrieval_receipts(id uuid primary key,cid varchar(120) not null,quote_id uuid not null references service_quotes(id),agent_id uuid,bytes_sent bigint not null,provider varchar(160),payment_channel varchar(160),voucher_nonce bigint,request_id varchar(128) not null unique,created_at timestamptz not null default now());
insert into schema_migrations(version) values('010_filecoin') on conflict do nothing;
